// Wavefont string encoding — one char per block from min/max block stats.
// Char U+0100–U+017F encodes peak-to-peak amplitude (128 levels); combining marks
// shift the bar to the block midpoint (center-aligned font, YELA 0): U+0302/U+030C
// = ±10 steps, U+0301/U+0300 = ±1, 10-step marks first — the canonical order the
// font's GPOS rules recognize (see .work/wavefont-quirks.md).
const LEVELS = 128, RANGE = 2

export function statsToWavefont(mins, maxs) {
  let str = ''
  for (let i = 0; i < maxs.length; i++) {
    let min = mins[i], max = maxs[i]
    let v = Math.min(LEVELS - 1, Math.max(0, Math.ceil(LEVELS * (max - min) / RANGE))) || 0
    let shift = Math.round(LEVELS * (max + min) / (2 * RANGE))
    let n = Math.abs(shift)
    str += String.fromCharCode(0x0100 + v)
    if (n) str += (shift > 0 ? '\u0302' : '\u030C').repeat(n / 10 | 0) + (shift > 0 ? '\u0301' : '\u0300').repeat(n % 10)
  }
  return str
}

// Unit tests for wavefont encoding — runs in Node.js
import test, { is } from 'tst'
import { statsToWavefont } from '../../src/waveform.js'

const UP10 = '\u0302', UP = '\u0301', DOWN10 = '\u030C', DOWN = '\u0300'

test('amplitude maps to U+0100..U+017F', () => {
  is(statsToWavefont([0], [0]), 'Ā') // silence
  is(statsToWavefont([-1], [1]), 'ſ') // full scale clamps to 127, not blank U+0180
  is(statsToWavefont([-2], [2]), 'ſ') // decoder overshoot clamps too
  is(statsToWavefont([0.05], [-0.05]), 'Ā') // garbage min>max clamps to 0
  is(statsToWavefont([], []), '')
})

test('symmetric blocks carry no marks', () => {
  is(statsToWavefont([-0.5], [0.5]), 'ŀ')
  is(statsToWavefont([-0.05, -1], [0.05, 1]), 'ćſ')
})

test('shift marks are canonical: 10-step first, then 1-step', () => {
  // min=-0.1 max=0.9 → v=64, shift=+26 → 2×up10 + 6×up
  is(statsToWavefont([-0.1], [0.9]), 'ŀ' + UP10.repeat(2) + UP.repeat(6))
  // mirrored down
  is(statsToWavefont([-0.9], [0.1]), 'ŀ' + DOWN10.repeat(2) + DOWN.repeat(6))
  // max shift: min=max=1 → v=0, shift=+64 → 6×up10 + 4×up (15 marks max per char)
  is(statsToWavefont([1], [1]), 'Ā' + UP10.repeat(6) + UP.repeat(4))
})

// API layer connecting UI, engine worker and storage.
// The whole audio engine (decode, PCM pages, stats, edits) lives in the worker;
// main thread receives only stat deltas (waveform strings) and playback windows.

import audioWorker from 'audio/worker'
import { createStore } from './store/index.js'
import { statsToWavefont } from './waveform.js'
import { BLOCK_SIZE } from './constants.js'

// budget: resident PCM cap in bytes forwarded to the engine (default: engine detects)
export default function createApi({ store, budget } = {}) {
  // string selects an adapter type ('opfs' | 'idb' | 'memory'), object is used as-is
  if (!store || typeof store === 'string') store = createStore(store || undefined)

  let a = null, worker = null
  // display block size — zoom level; ops/caret/URL coords are in bs units
  let bs = BLOCK_SIZE

  // absolute sample peak — >1 means the timeline clips on export
  let peakOf = (mins, maxs, from = 0) => {
    let p = 0
    for (let i = from; i < maxs.length; i++) { if (maxs[i] > p) p = maxs[i]; if (-mins[i] > p) p = -mins[i] }
    return p
  }

  // re-render full waveform + meta from engine state (edits applied)
  async function refresh() {
    let total = Math.ceil(a.length / bs)
    if (!total) return { waveform: '', total: 0, duration: 0, peak: 0 }
    let [mins, maxs] = await a.stat(['min', 'max'], { bins: total, channel: 0 })
    return { waveform: statsToWavefont(mins, maxs), total, duration: a.duration, peak: peakOf(mins, maxs) }
  }

  return {
    async loadFile(file, onWaveform) {
      // string source: remote URL goes straight to the engine (fetched in worker),
      // anything else is a store id
      if (typeof file === 'string' && !/^(https?|data|blob):/.test(file)) {
        file = await store.getFile(file)
      }

      // fresh engine per file — frees all decoded PCM of the previous one
      a?.dispose()
      worker?.terminate()
      worker = new Worker(new URL('./engine-worker.js', import.meta.url), { type: 'module' })
      // f stays bound to this load — a concurrent loadFile reassigns `a`
      let f = a = audioWorker(file, { worker, budget })

      // progressive render from stat deltas; emit strictly in block order —
      // if the 'data' subscription lands after decode started (FIFO race),
      // the missed prefix is healed by the full stat query below
      let next = 0, pending = new Map(), peak = 0
      f.on('data', ({ delta }) => {
        pending.set(delta.fromBlock, delta)
        while (pending.has(next)) {
          let d = pending.get(next)
          pending.delete(next)
          onWaveform(statsToWavefont(d.min[0], d.max[0]))
          peak = Math.max(peak, peakOf(d.min[0], d.max[0]))
          next += d.max[0].length
        }
      })

      await f.ready

      let total = Math.ceil(f.length / BLOCK_SIZE)
      if (next < total) {
        let [mins, maxs] = await f.stat(['min', 'max'], { bins: total, channel: 0 })
        onWaveform(statsToWavefont(mins.subarray(next), maxs.subarray(next)))
        peak = Math.max(peak, peakOf(mins, maxs, next))
      }

      return { duration: f.duration, channels: f.channels, sampleRate: f.sampleRate, peak }
    },

    // playback window — PCM transferred from the engine, never retained here
    getWindow(fromSample, toSample) {
      if (!a) return null
      let sr = a.sampleRate
      return a.read({ at: fromSample / sr, duration: toSample != null ? (toSample - fromSample) / sr : undefined })
    },

    // edit ops — offsets in blocks, engine takes samples;
    // op history/redo lives in UI state (URL ops), engine executes 1 edit per op
    async removeRange(fromBlock, toBlock, { replace } = {}) {
      if (replace) await a.undo()
      await a.run(['remove', { offset: fromBlock * bs, length: (toBlock - fromBlock) * bs }])
      return refresh()
    },

    async insertSilence(atBlock, nBlocks, { replace } = {}) {
      if (replace) await a.undo()
      await a.run(['insert', { source: nBlocks * bs / a.sampleRate, offset: atBlock * bs }])
      return refresh()
    },

    // trim to selection — keep only the range
    async cropRange(fromBlock, toBlock) {
      await a.run(['crop', { offset: fromBlock * bs, length: (toBlock - fromBlock) * bs }])
      return refresh()
    },

    // normalize the whole file — target: undefined = peak 0dB, number = peak dB,
    // string = LUFS preset (streaming/podcast/broadcast)
    async normalize(target) {
      let opts = target != null ? { target: isNaN(+target) ? target : +target } : {}
      await a.run(['normalize', opts])
      return refresh()
    },

    // compress silent pauses to `gap` seconds — whole file or range;
    // thr: silence threshold in dB (default: engine auto-detects)
    async shrink(fromBlock, toBlock, gap, thr) {
      let opts = gap != null ? { gap } : {}
      if (thr != null) opts.threshold = thr
      if (fromBlock != null) { opts.offset = fromBlock * bs; opts.length = (toBlock - fromBlock) * bs }
      await a.run(['shrink', opts])
      return refresh()
    },

    // amplify a range by dB (negative attenuates)
    async gain(fromBlock, toBlock, db) {
      await a.run(['gain', { value: db, offset: fromBlock * bs, length: (toBlock - fromBlock) * bs }])
      return refresh()
    },

    // [first, last) block exceeding the silence threshold (dB) — trim-edges bounds
    async edges(thr = -60) {
      let total = Math.ceil(a.length / bs)
      if (!total) return null
      let [mins, maxs] = await a.stat(['min', 'max'], { bins: total, channel: 0 })
      let lim = 10 ** (thr / 20)
      let f = 0, t = total
      while (f < total && Math.max(maxs[f], -mins[f]) < lim) f++
      while (t > f && Math.max(maxs[t - 1], -mins[t - 1]) < lim) t--
      return [f, t]
    },

    // fade over a range — dir: 1 = in, -1 = out; optional curve name
    async fadeRange(fromBlock, toBlock, dir, curve) {
      let opts = { in: dir * (toBlock - fromBlock) * bs / a.sampleRate, offset: fromBlock * bs }
      if (curve) opts.curve = curve
      await a.run(['fade', opts])
      return refresh()
    },

    // encode current timeline (edits applied); markers become WAV cue points.
    // onProgress receives {offset, total} in seconds per encoded chunk
    async encode(format, opts, onProgress) {
      if (!onProgress) return a.encode(format, opts)
      a.on('progress', onProgress)
      try { return await a.encode(format, opts) }
      finally { a.off('progress', onProgress) }
    },

    // clipboard — clone+crop snapshots the current timeline range, sample-precise
    // (clip() takes seconds and can drift ±1 sample → a stray partial block)
    async copyRange(fromBlock, toBlock) {
      let c = await a.clone()
      await c.run(['crop', { offset: fromBlock * bs, length: (toBlock - fromBlock) * bs }])
      return c
    },

    async pasteClip(clip, atBlock) {
      await a.run(['insert', { source: clip, offset: atBlock * bs }])
      return refresh()
    },

    // insert an external stored file at position — opens a second instance
    // on the same engine worker, inserted by ref
    async insertFile(atBlock, id) {
      let b = audioWorker(await store.getFile(id), { worker, budget })
      await b.ready
      await a.run(['insert', { source: b, offset: atBlock * bs }])
      let r = await refresh()
      r.src = b
      return r
    },

    setBlockSize(v) { bs = v },

    // full re-render at the current block size (zoom change, post-load)
    rerender() { return refresh() },

    // coarse whole-file min/max for the minimap
    async overview(bins) {
      if (!a?.length) return null
      let [mins, maxs] = await a.stat(['min', 'max'], { bins, channel: 0 })
      return { mins, maxs }
    },

    async undoEdit() {
      let edit = await a.undo()
      return edit ? refresh() : null
    },

    // replay an op chain (URL reconstruction) — sequential, single re-render.
    // cp ops reference the timeline state after their first v ops: clips for
    // v === k are snapshotted right before op k applies.
    async applyOps(ops) {
      let sr = a.sampleRate
      let clipAt = new Map() // v → [cp ops]
      for (let op of ops) if (op[0] === 'cp') {
        if (!clipAt.has(op[3])) clipAt.set(op[3], [])
        clipAt.get(op[3]).push(op)
      }
      let clips = new Map() // cp op → clip facade
      for (let k = 0; k <= ops.length; k++) {
        for (let cp of clipAt.get(k) || []) {
          let c = await a.clone()
          await c.run(['crop', { offset: cp[1] * bs, length: (cp[2] - cp[1]) * bs }])
          clips.set(cp, c)
        }
        if (k === ops.length) break
        let [type, ...args] = ops[k]
        if (type === 'del') await a.run(['remove', { offset: args[0] * bs, length: (args[1] - args[0]) * bs }])
        else if (type === 'sil') await a.run(['insert', { source: args[1] * bs / sr, offset: args[0] * bs }])
        else if (type === 'clip') await a.run(['crop', { offset: args[0] * bs, length: (args[1] - args[0]) * bs }])
        else if (type === 'cp') await a.run(['insert', { source: clips.get(ops[k]), offset: args[3] * bs }])
        else if (type === 'ins') {
          let b = audioWorker(await store.getFile(args[1]), { worker, budget })
          await b.ready
          await a.run(['insert', { source: b, offset: args[0] * bs }])
        }
        else if (type === 'norm') await a.run(['normalize', args[0] != null ? { target: isNaN(+args[0]) ? args[0] : +args[0] } : {}])
        else if (type === 'gain') await a.run(['gain', { value: args[2], offset: args[0] * bs, length: (args[1] - args[0]) * bs }])
        else if (type === 'shrink') {
          // trailing negative arg = silence threshold dB; rest is [gap] | [f, t, gap]
          let nums = [...args]
          let opts = nums[nums.length - 1] < 0 ? { threshold: nums.pop() } : {}
          if (nums.length > 1) { opts.offset = nums[0] * bs; opts.length = (nums[1] - nums[0]) * bs; opts.gap = (nums[2] ?? 300) / 1000 }
          else opts.gap = (nums[0] ?? 300) / 1000
          await a.run(['shrink', opts])
        }
        else if (type === 'fadein' || type === 'fadeout') {
          let d = (type === 'fadein' ? 1 : -1) * (args[1] - args[0]) * bs / sr
          let opts = { in: d, offset: args[0] * bs }
          if (args[2]) opts.curve = args[2]
          await a.run(['fade', opts])
        }
      }
      return refresh()
    },

    async saveFile(file, meta) {
      return store.addFile(file, meta);
    },

    async getFiles(options) {
      return store.getFiles(options);
    },

    async deleteFile(id) {
      return store.deleteFile(id);
    },

    async clearFiles() {
      return store.clearAll();
    },

    // storage usage/quota estimate — null when the adapter can't tell
    async storeInfo() {
      return store.getStoreInfo?.() ?? null;
    }
  }
}

// Playback engine — thin interface over 2 backends
// Primary: AudioBufferSourceNode (works everywhere incl iOS)
// Fallback: <audio> element (no AudioContext — encodes WAV blob)
// Future: AudioWorklet (Phase 3 — effects, crossfade, recording)

import { BLOCK_SIZE } from './constants.js'

// engine interface:
//   play(fromBlock, toBlock, loop) → void
//   pause() → void
//   seek(block) → void
//   setLoop(start, end) → void
//   setVolume(v) → void
//   setSpeed(r) → void
//   destroy() → void
//   state: 'stopped' | 'playing' | 'paused'
//   onstarted({block, time}) — emitted when playback starts
//   onlooped({block}) — emitted when loop restarts
//   onended() — emitted when playback reaches end

const engines = { buffer: bufferPlayer, audio: audioElPlayer, worklet: workletPlayer }

export default function createPlayer(getWindow, { sampleRate = 44100, channels = 1, engine, blockSize } = {}) {
  let gbs = blockSize ?? (() => BLOCK_SIZE)  // live accessor — zoom changes block size
  if (engine) return engines[engine](getWindow, sampleRate, channels, gbs)
  if (typeof AudioContext !== 'undefined' || typeof webkitAudioContext !== 'undefined') {
    return bufferPlayer(getWindow, sampleRate, channels, gbs)
  }
  return audioElPlayer(getWindow, sampleRate, channels, gbs)
}

export { bufferPlayer, audioElPlayer, workletPlayer }


// Primary backend: AudioBufferSourceNode
const FADE_TIME = 0.015 // 15ms fade in/out to eliminate clicks
const MAX_BUFFER_SEC = 10 // cap AudioBuffer — Safari postMessage is slow for large transfers

function bufferPlayer(getWindow, sr, ch, gbs = () => BLOCK_SIZE) {
  let ctx = new (window.AudioContext || window.webkitAudioContext)({ latencyHint: 'interactive', ...(sr ? { sampleRate: sr } : {}) })
  // warm up AudioContext + audio pipeline (Safari has cold-start latency)
  if (ctx.state === 'suspended') ctx.resume()
  // play silent buffer to prime the audio output path
  let warmup = ctx.createBufferSource()
  warmup.buffer = ctx.createBuffer(1, 1, sr)
  warmup.connect(ctx.destination)
  warmup.start(0)
  let gain = ctx.createGain()
  gain.connect(ctx.destination)
  let vol = 1

  let fadeTo = (v) => {
    gain.gain.cancelScheduledValues(ctx.currentTime)
    gain.gain.setValueAtTime(gain.gain.value, ctx.currentTime)
    gain.gain.linearRampToValueAtTime(v, ctx.currentTime + FADE_TIME)
  }

  let source = null
  let nextSrc = null   // prefetched continuation window, start()-scheduled at the seam
  let chainGen = 0     // invalidates in-flight prefetches
  let speed = 1
  let loopStartBlock = 0, loopEndBlock = 0, isLooping = false
  let playAbort = false // flag to cancel pending async play

  // fetch a window into a ready-to-start source node (capped at MAX_BUFFER_SEC,
  // block-aligned so consecutive windows are sample-contiguous at the seam)
  async function makeSource(fromBlock, toBlock, loop) {
    let fromSample = fromBlock * gbs()
    let toSample = toBlock != null ? toBlock * gbs() : undefined
    let maxSamples = loop ? undefined : Math.floor(MAX_BUFFER_SEC * sr / gbs()) * gbs()
    if (maxSamples && toSample != null && toSample - fromSample > maxSamples) toSample = fromSample + maxSamples
    else if (maxSamples && toSample == null) toSample = fromSample + maxSamples

    let pcm = getWindow(fromSample, toSample)
    if (pcm?.then) pcm = await pcm
    if (!pcm || !pcm[0]?.length) return null

    let frames = pcm[0].length
    let buf = ctx.createBuffer(ch, frames, sr)
    for (let i = 0; i < ch; i++) buf.copyToChannel(pcm[i] || pcm[0], i)

    let s = ctx.createBufferSource()
    s.buffer = buf
    s.playbackRate.value = speed
    s.loop = loop
    if (loop) { s.loopStart = 0; s.loopEnd = frames / sr }
    s.connect(gain)
    s._fromBlock = fromBlock
    s._endBlock = toSample != null ? Math.ceil(toSample / gbs()) : toBlock
    s._frames = frames
    return s
  }

  let killSrc = s => { if (!s) return; s.onended = null; try { s.stop() } catch {}; try { s.disconnect() } catch {} }

  // prefetch the next contiguous window and start() it at the exact seam —
  // gapless steady state; a mid-window speed change drops the schedule and
  // that one seam falls back to fetch-on-end
  function scheduleNext(cur) {
    let gen = ++chainGen
    makeSource(cur._endBlock, loopEndBlock, false).then(s => {
      if (!s) return
      if (gen !== chainGen || playAbort || source !== cur || player.state !== 'playing') return killSrc(s)
      let endAt = cur._startAt + cur._frames / sr / speed
      s._startAt = Math.max(endAt, ctx.currentTime)
      s._scheduled = true
      s.onended = () => onWindowEnd(s)
      s.start(s._startAt)
      nextSrc = s
    }).catch(() => {})
  }

  function dropScheduled() {
    chainGen++
    killSrc(nextSrc)
    nextSrc = null
  }

  function onWindowEnd(s) {
    if (player.state !== 'playing' || s !== source) return
    // seam: the scheduled next window is already sounding — promote it
    if (nextSrc?._scheduled) {
      source = nextSrc
      nextSrc = null
      player.onstarted?.({ block: source._fromBlock, time: source._startAt })
      if (source._endBlock != null && loopEndBlock != null && source._endBlock < loopEndBlock) scheduleNext(source)
      return
    }
    // no schedule (dropped by a speed change) — refetch, small one-time gap
    if (s._endBlock != null && loopEndBlock != null && s._endBlock < loopEndBlock) {
      player.play(s._endBlock, loopEndBlock, false)
      return
    }
    player.state = 'stopped'
    source = null
    player.onended?.()
  }

  let player = {
    state: 'stopped',
    onstarted: null,
    onlooped: null,
    onended: null,

    async play(fromBlock = 0, toBlock, loop = false) {
      playAbort = false
      console.time('[bufferPlayer.play]')
      if (ctx.state === 'suspended') await ctx.resume()
      if (playAbort) return

      // fade out + stop previous without triggering onended
      dropScheduled()
      if (source) {
        fadeTo(0)
        source.onended = null
        source.stop(ctx.currentTime + FADE_TIME)
      }

      loopStartBlock = fromBlock
      loopEndBlock = toBlock
      isLooping = loop

      let s = await makeSource(fromBlock, toBlock, loop)
      if (playAbort) return killSrc(s)
      if (!s) return

      source = s
      s._startAt = ctx.currentTime
      s.onended = () => onWindowEnd(s)

      // fade in from silence
      gain.gain.setValueAtTime(0, ctx.currentTime)
      fadeTo(vol)
      s.start(s._startAt)
      console.timeEnd('[bufferPlayer.play]')
      player.state = 'playing'
      player.onstarted?.({ block: fromBlock, time: s._startAt })
      if (!loop && s._endBlock != null && toBlock != null && s._endBlock < toBlock) scheduleNext(s)
    },

    pause() {
      playAbort = true
      dropScheduled()
      if (source && player.state === 'playing') {
        // fade out then disconnect (click-free stop)
        fadeTo(0)
        source.onended = null
        let s = source
        source = null
        // disconnect after fade completes
        setTimeout(() => { try { s.stop(); s.disconnect() } catch {} }, FADE_TIME * 1000 + 5)
      }
      player.state = 'paused'
    },

    seek(block) {
      let wasPlaying = player.state === 'playing'
      dropScheduled()
      if (source) { try { source.stop() } catch {} }
      source = null
      if (wasPlaying) player.play(block)
    },

    setLoop(start, end) {
      loopStartBlock = start
      loopEndBlock = end
    },

    setVolume(v) {
      vol = v
      fadeTo(v)
    },

    setSpeed(r) {
      speed = r
      if (source) source.playbackRate.value = r
      // projected seam moved — drop the schedule, that boundary refetches
      dropScheduled()
    },

    destroy() {
      dropScheduled()
      if (source) { source.onended = null; try { source.stop() } catch {} }
      source = null
      ctx.close()
      player.state = 'stopped'
    },

    get currentTime() { return ctx.currentTime },
    get sampleRate() { return sr },
    get loopStart() { return loopStartBlock },
    get loopEnd() { return loopEndBlock },
    get loop() { return isLooping }
  }

  return player
}


// encode PCM to WAV blob
function encodeWAV(pcm, sr, ch) {
  let frames = pcm[0].length
  let bytesPerSample = 2
  let dataLen = frames * ch * bytesPerSample
  let buf = new ArrayBuffer(44 + dataLen)
  let view = new DataView(buf)

  // RIFF header
  let writeStr = (off, str) => { for (let i = 0; i < str.length; i++) view.setUint8(off + i, str.charCodeAt(i)) }
  writeStr(0, 'RIFF')
  view.setUint32(4, 36 + dataLen, true)
  writeStr(8, 'WAVE')
  writeStr(12, 'fmt ')
  view.setUint32(16, 16, true) // subchunk size
  view.setUint16(20, 1, true) // PCM
  view.setUint16(22, ch, true)
  view.setUint32(24, sr, true)
  view.setUint32(28, sr * ch * bytesPerSample, true)
  view.setUint16(32, ch * bytesPerSample, true)
  view.setUint16(34, bytesPerSample * 8, true)
  writeStr(36, 'data')
  view.setUint32(40, dataLen, true)

  // interleave channels and convert f32 → i16
  let off = 44
  for (let i = 0; i < frames; i++) {
    for (let c = 0; c < ch; c++) {
      let s = Math.max(-1, Math.min(1, pcm[c]?.[i] || 0))
      view.setInt16(off, s * 0x7FFF, true)
      off += 2
    }
  }

  return new Blob([buf], { type: 'audio/wav' })
}


// Fallback backend: <audio> element with WAV blob
function audioElPlayer(getWindow, sr, ch, gbs = () => BLOCK_SIZE) {
  let el = document.createElement('audio')
  let blobUrl = null
  let speed = 1
  let startBlock = 0, isLooping = false

  let player = {
    state: 'stopped',
    onstarted: null,
    onlooped: null,
    onended: null,

    async play(fromBlock = 0, toBlock, loop = false) {
      if (blobUrl) URL.revokeObjectURL(blobUrl)

      startBlock = fromBlock
      isLooping = loop

      let fromSample = fromBlock * gbs()
      let toSample = toBlock != null ? toBlock * gbs() : undefined

      let pcm = await getWindow(fromSample, toSample)
      if (!pcm || !pcm[0]?.length) return

      let blob = encodeWAV(pcm, sr, ch)
      blobUrl = URL.createObjectURL(blob)
      el.src = blobUrl
      el.loop = loop
      el.playbackRate = speed
      await el.play()

      player.state = 'playing'
      player.onstarted?.({ block: fromBlock, time: performance.now() / 1000 })
    },

    pause() {
      el.pause()
      player.state = 'paused'
    },

    seek(block) {
      let wasPlaying = player.state === 'playing'
      el.pause()
      if (wasPlaying) player.play(block)
    },

    setLoop(start, end) { startBlock = start; el.loop = true },
    setVolume(v) { el.volume = v },
    setSpeed(r) {
      speed = r
      el.playbackRate = r
    },
    destroy() {
      el.pause()
